#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"


/* Array initialization. */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++)
	A[i][j][k] = (DATA_TYPE) ((i*j + k)%np) / np;
  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++)
      C4[i][j] = (DATA_TYPE) (i*j % np) / np;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation:

     for (r)
       for (q)
         for (p) {
           sum[p] = 0;
           for (s)
             sum[p] += A[r][q][s] * C4[s][p];
         }
         for (p)
           A[r][q][p] = sum[p];

   This computes, for each fixed (r,q), a matrix-vector–like product:
     sum[p] = Σ_s A[r][q][s] * C4[s][p]
   and then writes back sum[p] into A[r][q][p].

   Optimization applied:

   1. Move the initialization of sum[p] outside the inner loops and
      initialize the entire sum array once per (r,q) pair.

   2. Swap the (p,s) loop nest to (s,p). With C’s row-major layout,
      this makes p the innermost index for C4[s][p], so we traverse
      each row of C4 contiguously and reuse A[r][q][s] across all p.
      This greatly improves cache locality and enables more effective
      vectorization, while preserving the exact numerical result.
*/
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {

      /* Pointer to the current (r,q) row of A.
         A[r][q] is a 1D array of length NP and decays to a DATA_TYPE*. */
      DATA_TYPE *A_rq = A[r][q];

      /* Initialize the temporary accumulation buffer 'sum' once per (r,q).
         In the original code, each sum[p] was set to 0.0 before its
         accumulation over s. After this loop, all entries are zero, so
         the state before starting the accumulation is identical. */
      for (p = 0; p < _PB_NP; p++)
        sum[p] = SCALAR_VAL(0.0);

      /* Reordered loops:
           - Outer loop over s iterates along A_rq[s] contiguously.
           - Inner loop over p walks along the row C4[s][p] contiguously.

         This computes:
           sum[p] = Σ_s A_rq[s] * C4[s][p]
         which is the same expression as in the original kernel, but
         with a cache- and vectorization-friendly access pattern. */
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_rqs = A_rq[s];   /* Load A[r][q][s] once and reuse. */
        DATA_TYPE *C4_s = C4[s];     /* Pointer to row s of C4. */

        for (p = 0; p < _PB_NP; p++) {
          sum[p] += a_rqs * C4_s[p];
        }
      }

      /* Copy the accumulated result back into the corresponding row of A. */
      for (p = 0; p < _PB_NP; p++)
        A_rq[p] = sum[p];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
