/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen [[gnu::flatten, gnu::noinline]] (int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Effective problem sizes. Using local constants for the loop bounds
   * helps the compiler optimize and makes it explicit that they do not
   * change inside the kernel. */
  const int NR_ = _PB_NR;
  const int NQ_ = _PB_NQ;
  const int NP_ = _PB_NP;

  /* Create restrict-qualified local pointers. In PolyBench, A, C4 and
   * sum are allocated independently and never alias, so adding
   * restrict here is valid and enables better optimization. */
  DATA_TYPE (*restrict A_)[nq][np] = A;
  DATA_TYPE (*restrict C4_)[np]    = C4;
  DATA_TYPE *restrict sum_         = sum;

#pragma scop
  /* For each (r, q) pair, we compute:
   *
   *   A[r][q][p] = sum_{s=0..NP-1} A[r][q][s] * C4[s][p]
   *
   * The original code used loop order (r, q, p, s). Here we use
   * (r, q, s, p) to improve locality on C4:
   *  - For each fixed s, the access C4[s][p] with p in the innermost
   *    loop is contiguous in memory (row-major order).
   *  - For each fixed (r, q, p), the accumulation over s still occurs
   *    in strictly increasing order of s, so the floating-point
   *    results are bit-identical to the original implementation.
