  {
    for (q = 0; q < NQ_; q++)
    {
      /* Pointer to the contiguous row A[r][q][:]. */
      DATA_TYPE *restrict A_rq = &A_[r][q][0];

      /* Initialize the accumulation buffer once per (r, q). This is
       * equivalent to the original code, which set sum[p] to zero
       * for each p before its inner s-loop. */
      for (p = 0; p < NP_; p++)
        sum_[p] = SCALAR_VAL(0.0);

      /* Accumulate contributions from each s. */
      for (s = 0; s < NP_; s++)
      {
        const DATA_TYPE a_val = A_rq[s];
        DATA_TYPE *restrict C4_row = &C4_[s][0];

        /* No loop-carried dependencies across p: each iteration
         * updates a distinct element of sum_. This is a good target
         * for auto-vectorization. */
        #pragma GCC ivdep
        for (p = 0; p < NP_; p++)
          sum_[p] += a_val * C4_row[p];
      }

      /* Write the result back to A[r][q][:]. Leaving this as a separate
       * copy step preserves the final content of `sum` (it remains equal
       * to the last computed A[r][q] row), matching the original code's
       * observable behavior. */
      for (p = 0; p < NP_; p++)
        A_rq[p] = sum_[p];
    }
  }
#pragma endscop
}


