         - A[r][q][s] is read in a streaming fashion in s.
         - C4[s][p] is accessed row-wise (p is the innermost index),
           which matches C row-major layout and is cache-friendly.
         - The innermost loop over p is a simple, contiguous
           vector operation, enabling efficient SIMD code generation. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_rqs = A_rq[s];
        const DATA_TYPE *restrict C4_row = C4_[s];

        for (p = 0; p < _PB_NP; p++) {
          sum_[p] += a_rqs * C4_row[p];
        }
      }

      /* 3. Copy the accumulated result back into A.
         This remains a separate loop so that all computations above
         are performed using the *original* values of A[r][q][s],
         exactly as in the reference implementation. */
      for (p = 0; p < _PB_NP; p++) {
        A_rq[p] = sum_[p];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

